WITH target(name) AS (VALUES ('Store'),('Booking'),('Customer'),('Staff'),('ServicePlan'),('Transaction'),('DigitalButlerLead'),('SessionBalanceNotification'),('CourseBooking'),('CourseSession'),('SteamfootStoreNotice'),('SteamfootNoticeSetting')),
relations AS (SELECT c.oid,c.relname,c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.relacl FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN target t ON t.name=c.relname WHERE n.nspname='public'),
funcs AS (SELECT p.oid,p.proname,p.prosrc,p.proconfig,p.prosecdef,p.proacl,pg_get_userbyid(p.proowner) AS owner FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('record_steamfoot_store_notice','record_steamfoot_plan_payment_notice','record_digital_manager_lead_notice','record_digital_manager_vip_notice','resolve_steamfoot_incomplete_notice','resolve_course_incomplete_notice','resolve_course_session_incomplete_notices')),
role AS (SELECT oid,rolname,rolcanlogin,rolsuper,rolbypassrls,rolinherit FROM pg_roles WHERE rolname='steamfoot_beauty_prod_20261025'),
snapshot AS (SELECT jsonb_build_object(
 'relations',COALESCE((SELECT jsonb_agg(jsonb_build_array(relname,relkind,relrowsecurity,relforcerowsecurity,relacl) ORDER BY relname) FROM relations),'[]'::jsonb),
 'columns',COALESCE((SELECT jsonb_agg(jsonb_build_array(r.relname,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) ORDER BY r.relname,a.attnum) FROM relations r JOIN pg_attribute a ON a.attrelid=r.oid AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum),'[]'::jsonb),
 'constraints',COALESCE((SELECT jsonb_agg(jsonb_build_array(r.relname,c.conname,c.contype,pg_get_constraintdef(c.oid),c.convalidated) ORDER BY r.relname,c.conname) FROM relations r JOIN pg_constraint c ON c.conrelid=r.oid),'[]'::jsonb),
 'indexes',COALESCE((SELECT jsonb_agg(jsonb_build_array(r.relname,i.relname,pg_get_indexdef(i.oid),x.indisvalid,x.indisready) ORDER BY r.relname,i.relname) FROM relations r JOIN pg_index x ON x.indrelid=r.oid JOIN pg_class i ON i.oid=x.indexrelid),'[]'::jsonb),
 'policies',COALESCE((SELECT jsonb_agg(jsonb_build_array(r.relname,p.polname,p.polcmd,p.polpermissive,p.polroles,pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY r.relname,p.polname) FROM relations r JOIN pg_policy p ON p.polrelid=r.oid),'[]'::jsonb),
 'triggers',COALESCE((SELECT jsonb_agg(jsonb_build_array(r.relname,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid)) ORDER BY r.relname,t.tgname) FROM relations r JOIN pg_trigger t ON t.tgrelid=r.oid AND NOT t.tgisinternal),'[]'::jsonb),
 'functions',COALESCE((SELECT jsonb_agg(jsonb_build_array(proname,md5(prosrc),proconfig,prosecdef,proacl,owner) ORDER BY proname,oid) FROM funcs),'[]'::jsonb),
 'role',COALESCE((SELECT jsonb_agg(jsonb_build_array(rolname,rolcanlogin,rolsuper,rolbypassrls,rolinherit) ORDER BY rolname) FROM role),'[]'::jsonb),
 'role_membership',COALESCE((SELECT jsonb_agg(jsonb_build_array(parent.rolname,m.admin_option) ORDER BY parent.rolname) FROM role r JOIN pg_auth_members m ON m.member=r.oid JOIN pg_roles parent ON parent.oid=m.roleid),'[]'::jsonb),
 'role_columns',COALESCE((SELECT jsonb_agg(jsonb_build_array(a.attname,has_column_privilege(r.oid,a.attrelid,a.attnum,'SELECT')) ORDER BY a.attname) FROM role r JOIN pg_class c ON c.relname='Store' JOIN pg_namespace n ON n.oid=c.relnamespace AND n.nspname='public' JOIN pg_attribute a ON a.attrelid=c.oid AND a.attname IN ('id','industryModule')),'[]'::jsonb)
 ) AS value)
SELECT md5(value::text) AS fingerprint,jsonb_array_length(value->'relations') AS relation_count,jsonb_array_length(value->'functions') AS function_count FROM snapshot;
